def tours_to_headliners(apps, schema_editor):
    """Every existing non-festival production is the headliner's tour at each of its events."""
    Event = apps.get_model("events", "Event")
    EventPerformer = apps.get_model("events", "EventPerformer")
    for event in Event.objects.exclude(production=None).select_related("production"):
        production = event.production
        if production.event_type == "festival":
            continue  # festivals keep grouping whole events
        headliner = EventPerformer.objects.filter(event=event).order_by("billing_order", "pk").first()
        if headliner:
            if not headliner.production_id:
                headliner.production = production
                headliner.save(update_fields=["production"])
            if not production.performer_id:
                production.performer_id = headliner.performer_id
                production.save(update_fields=["performer"])
        event.production = None
        event.save(update_fields=["production"])


